dict(toc='Contempt of court', id=54, title='CONTEMPT OF COURT', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 20-22',
 simple='Courts can punish contempt under Arts 129 and 215 and the 1971 Act. The trouble is vagueness: scandalising the court, judge in own cause, intent vs effect. Mulgaokar (1978) says use sparingly; the UK abolished scandalising in 2013. Reform: objective standards.',
 nodes=[
 sec('MEANING AND TYPES', 'b'),
 t('<b>Constitutional and statutory basis</b>',
   '<b>Contempt of Courts Act, 1971</b> defines and regulates it',
   '<b>Art 129:</b> Supreme Court is a <b>Court of Record</b> and can punish its own contempt',
   '<b>Art 215:</b> same for <b>High Courts</b>'),
 two([t('<b>Civil contempt</b>', '<b>wilful disobedience</b> of any judgment, decree, direction, order, writ or process', 'or <b>wilful breach of an undertaking</b> given to a court')],
     [t('<b>Criminal contempt</b>', '<b>scandalising</b> or lowering the authority of a court', '<b>prejudicing or interfering</b> with judicial proceedings', 'interfering with or <b>obstructing the administration of justice</b> in any other way')]),
 bx('pk', '<b>Why the power exists:</b> unpopular rulings can trigger campaigns that undermine the <b>independence and authority</b> of the judiciary; without independence the <b>public interest</b> suffers.'),
 sec('ISSUES', 'r'),
 t('<b>Five issues</b>',
   '<b>Nemo judex in causa sua</b> (no one is judge in their own cause): the court whose authority is attacked may itself decide the contempt',
   '<b>Vagueness:</b> "scandalising the court"; no objective yardstick; depends on judges\' <b>subjective assessment</b>, so outcomes vary, which touches <b>equality before law</b>; broad use <b>stifles genuine criticism</b>',
   '<b>Intent vs effect:</b> proceedings may look at the <b>tendency</b> of criticism rather than <b>mens rea</b>; relevance of intention depends on the type of contempt',
   '<b>Impression of infallibility:</b> judges are human; just criticism of a judge is not criticism obstructing the institution',
   '<b>Judge vs court:</b> contempt of court is not contempt of an individual judge; the line blurs'),
 OWN('NVIJ', 'Issues: <b>N</b>emo judex · <b>V</b>agueness · <b>I</b>ntent vs effect · <b>I</b>nfallibility · <b>J</b>udge vs court.'),
 bx('ye', '<b>In Re S. Mulgaokar (1978):</b> Justice <b>V. R. Krishna Iyer</b>: judges should have <b>broad shoulders</b>; protect the <b>administration of justice</b>, not the personal reputation of judges.'),
 t('<b>Mulgaokar guidelines</b>',
   '<b>sparing use</b>; not every criticism merits contempt',
   'act seriously when an attack is <b>calculated to obstruct or destroy</b> the judicial process',
   '<b>distinguish judge from court</b>',
   '<b>press freedom:</b> the press may criticise courts within responsible limits',
   '<b>judicial restraint</b> even if language is harsh',
   'for <b>malicious or intimidatory</b> attacks, use contempt in the public interest'),
 sec('SAFEGUARDS IN THE 1971 ACT', 'g'),
 t('<b>Section 13 and Section 15</b>',
   '<b>s.13:</b> no sentence unless the contempt <b>substantially interferes</b> with due course of justice; after the <b>2006 amendment</b> <b>truth is a defence</b> if in <b>public interest</b> and <b>bona fide</b>',
   '<b>s.15:</b> criminal contempt (other than in the court\'s presence): <b>suo motu</b> by SC or HC; others need <b>consent of the Attorney General or Solicitor General (SC)</b> or <b>Advocate General (HC)</b>; consent rule does <b>not restrict suo motu</b> jurisdiction'),
 sec('COMPARISONS AND REFORM', 'b'),
 tb(['Country', 'Position'],
    ['<b>UK</b>', '<b>abolished scandalising the judiciary</b> as contempt in England and Wales in <b>2013</b>; "old fools" illustration: being old is a fact, being a fool is opinion'],
    ['<b>USA</b>', 'strong free-expression protection; contempt is <b>more restrictive</b> for criticism outside the courtroom']),
 t('<b>Reform agenda</b>',
   '<b>objective standards</b> in place of vague phrases (Art 19(1)(a) compatibility)',
   '<b>criticism is not obstruction</b>; keep contempt for conduct that obstructs justice',
   '<b>judicial accountability:</b> criticism improves institutions',
   'protect the <b>administration of justice, not judges\' reputation</b>'),
 ],
 recall=[('Contempt Act year', '1971'), ('Articles on contempt power', '129 (SC) and 215 (HC)'), ('Civil contempt', 'wilful disobedience or breach of undertaking'), ('Criminal contempt', 'scandalising, prejudicing proceedings, obstructing justice'), ('Nemo judex', 'no one is judge in their own cause'), ('Mulgaokar 1978 words', 'broad shoulders (Krishna Iyer)'), ('Truth as defence', 'section 13, after 2006 amendment, public interest and bona fide'), ('UK abolished scandalising in', '2013')]),

